mapper.select:
SELECT WORKBOOK_SEQ, STARRED_YN, COLOR_CODE
  FROM wo_user_workbook_mark
 WHERE USER_KEY = #{userKey}

mapper.delete:
DELETE FROM wo_user_workbook_mark
 WHERE USER_KEY = #{userKey}
   AND WORKBOOK_SEQ = #{workbookSeq}

mapper.insert:
INSERT INTO wo_user_workbook_mark (
    USER_KEY, WORKBOOK_SEQ, STARRED_YN, COLOR_CODE, INPUT_DATETIME, INPUT_USER
) VALUES (
    #{userKey}, #{workbookSeq}, #{starredYn}, #{colorCode}, CURRENT_TIMESTAMP, #{userKey}
)
ON CONFLICT (USER_KEY, WORKBOOK_SEQ) DO UPDATE SET
    STARRED_YN   = #{starredYn},
    COLOR_CODE   = #{colorCode},
    MOD_DATETIME = CURRENT_TIMESTAMP,
    MOD_USER      = #{userKey}

mapper.select:
SELECT COLOR_CODE, LABEL_NAME
  FROM wo_user_color_label
 WHERE USER_KEY = #{userKey}

mapper.delete:
DELETE FROM wo_user_color_label
 WHERE USER_KEY = #{userKey}
   AND COLOR_CODE = #{colorCode}

mapper.insert:
MERGE INTO wo_user_color_label T
USING (SELECT CAST(#{userKey} AS VARCHAR) AS USER_KEY,
              CAST(#{colorCode} AS VARCHAR) AS COLOR_CODE) S
   ON (T.USER_KEY = S.USER_KEY AND T.COLOR_CODE = S.COLOR_CODE)
WHEN MATCHED THEN UPDATE SET
     LABEL_NAME   = #{labelName},
     MOD_DATETIME = CURRENT_TIMESTAMP,
     MOD_USER      = #{userKey}
WHEN NOT MATCHED THEN INSERT (
     USER_KEY, COLOR_CODE, LABEL_NAME, INPUT_DATETIME, INPUT_USER
) VALUES (
     #{userKey}, #{colorCode}, #{labelName}, CURRENT_TIMESTAMP, #{userKey}
)

INSERT INTO wo_user_color_label (
    USER_KEY, COLOR_CODE, LABEL_NAME, INPUT_DATETIME, INPUT_USER
) VALUES (
    #{userKey}, #{colorCode}, #{labelName}, CURRENT_TIMESTAMP, #{userKey}
)
ON CONFLICT (USER_KEY, COLOR_CODE) DO UPDATE SET
    LABEL_NAME   = #{labelName},
    MOD_DATETIME = CURRENT_TIMESTAMP,
    MOD_USER      = #{userKey}
